$Manifest = @()
try {
  foreach ($File in $Files) {
    $Target = [IO.Path]::GetFullPath((Join-Path $TestRoot $File.Path))
    if (-not $Target.StartsWith($TestRoot + [IO.Path]::DirectorySeparatorChar, [StringComparison]::Ordinal)) { throw "Unsafe target: $Target" }
    $Existed = Test-Path -LiteralPath $Target -PathType Leaf
    $Backup = Join-Path $BackupRoot $File.Path
    if ($Existed) { New-Item -ItemType Directory -Path (Split-Path $Backup -Parent) -Force | Out-Null; Copy-Item -LiteralPath $Target -Destination $Backup -Force }
    $Manifest += [pscustomobject]@{ Path = $File.Path; Existed = $Existed; Backup = $(if ($Existed) { $Backup } else { $null }) }
  }
  $Manifest | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $BackupRoot "rollback-manifest.json") -Encoding utf8
  foreach ($File in $Files) {
    $Target = Join-Path $TestRoot $File.Path
    New-Item -ItemType Directory -Path (Split-Path $Target -Parent) -Force | Out-Null
    [IO.File]::WriteAllBytes($Target, [Convert]::FromBase64String($File.Content))
    $Actual = (Get-FileHash -LiteralPath $Target -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($Actual -ne $File.Sha256) { throw "Verification failed for $($File.Path): expected $($File.Sha256), got $Actual" }
    Write-Host "VERIFIED $($File.Path) $Actual" -ForegroundColor Green
  }
  Write-Host "SUCCESS: TEST-only two-node cluster GPU arbitration patch applied and verified." -ForegroundColor Green
  Write-Host "Backup root: $BackupRoot"
  Write-Host "ROLLBACK (PowerShell):" -ForegroundColor Yellow
  Write-Host '$items = Get-Content -Raw "<BACKUP_ROOT>/rollback-manifest.json" | ConvertFrom-Json'
  Write-Host 'foreach ($item in $items) { $target = Join-Path "/home/shawn-rochford/AI/work/OTG-Test-Runtime-Publish-20260813" $item.Path; if ($item.Existed) { Copy-Item -LiteralPath $item.Backup -Destination $target -Force } elseif (Test-Path -LiteralPath $target) { Remove-Item -LiteralPath $target -Force } }'
} catch {
  Write-Error ("FAILED: " + $_.Exception.Message)
  Write-Host "No automatic rollback was attempted. Restore from: $BackupRoot" -ForegroundColor Yellow
  exit 1
}
